/* Legacy links from the former in-page kits view. */
if(location.hash==="#kits")location.replace("kits.html");
function scrollToStory(){if(location.hash==="#story")setTimeout(()=>$("#story").scrollIntoView({behavior:"instant"}),30)}
if($("#story")){addEventListener("hashchange",scrollToStory);scrollToStory()}
if($("#jr")){/* journey + parallax */
const jr=$("#jr"),chs=$$(".ch"),rb=$$("#rail button");let cur=-1;
function setCh(i){if(i===cur)return;cur=i;chs.forEach((c,j)=>c.classList.toggle("on",j===i));rb.forEach((b,j)=>b.classList.toggle("on",j<=i))}
function tick(){if($("#home").hidden)return;const r=jr.getBoundingClientRect(),t=r.height-innerHeight,p=Math.min(Math.max(-r.top/t,0),.999);setCh(Math.floor(p*5));$("#sc").classList.toggle("off",cur>0);
const b=$(".band").getBoundingClientRect();$("#par").style.transform=`translateY(${(b.top+b.height/2-innerHeight/2)*-.12}px)`}
let raf;addEventListener("scroll",()=>{cancelAnimationFrame(raf);raf=requestAnimationFrame(tick)},{passive:true});
rb.forEach(b=>b.onclick=()=>{const t=jr.offsetHeight-innerHeight;scrollTo({top:jr.offsetTop+t*(+b.dataset.i+.5)/5})});
new IntersectionObserver((es,o)=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add("in");o.unobserve(e.target)}}),{threshold:.5}).observe($("#paper"));
$$(".fr").forEach(f=>{const u=PHOTOS[f.dataset.p];if(u){f.style.backgroundImage=`url("${u}")`;f.style.backgroundPosition=POS[f.dataset.p];f.classList.add("has")}});
tick();
}
/* intro video: plays once per visit, then fades into the site */
(function(){const o=$("#intro"),v=o.querySelector("video");let seen=false;try{seen=sessionStorage.getItem("rb_intro")}catch(e){}
const reduce=matchMedia("(prefers-reduced-motion:reduce)").matches;
function done(){if(o.dataset.d)return;o.dataset.d=1;try{sessionStorage.setItem("rb_intro","1")}catch(e){}o.classList.add("out");document.body.style.overflow="";document.body.classList.add("load");scrollToStory();setTimeout(()=>o.remove(),800)}
if(seen||reduce){o.remove();document.body.classList.add("load");scrollToStory()}
else{document.body.style.overflow="hidden";v.addEventListener("ended",done);v.addEventListener("error",done);$("#skip").onclick=done;const pr=v.play();if(pr&&pr.catch)pr.catch(done);setTimeout(()=>{if(v.readyState<2)done()},4000)}})();
